<?php
namespace Tests\Unit;
use App\Services\SpeakerIdentityPolicy as Policy;
use App\Services\SpeakerTaggingService;
use App\Services\TranscriptSegmentMapper;
use Tests\TestCase;
class SpeakerIdentityTest extends TestCase {
 protected function setUp():void {parent::setUp();config(['speaker-identification.revision'=>'fixture-v1','speaker-identification.threshold'=>75,'speaker-identification.margin'=>15,'speaker-identification.min_speech_seconds'=>3]);}
 private function sample($id=1,$identity='one'):array{return ['id'=>$id,'identity_key'=>$identity,'name'=>'Name '.$identity,'voiceprint'=>base64_encode('opaque-'.$id),'voiceprint_model'=>'precision-2','voiceprint_revision'=>'fixture-v1','validation_state'=>'approved','duration'=>20,'quality_review'=>['single_speaker'=>true,'usable_speech'=>true,'silence'=>false,'noise'=>false,'music'=>false,'overlap'=>false,'clipping'=>false,'sample_rate_hz'=>16000]];}
 private function enrollment():array{return (new Policy)->enroll([$this->sample(),$this->sample(2,'two')])['samples'];}
 private function providerOutput($scores=['sample:1'=>90,'sample:2'=>20]):array{return ['diarization'=>[['speaker'=>'SPEAKER_00','start'=>0,'end'=>5]],'voiceprints'=>[['speaker'=>'SPEAKER_00','match'=>'sample:1','confidence'=>$scores]]];}
 public function test_missing_and_malformed_voiceprints_are_excluded():void {foreach([null,'','not base64!!']as$value){$s=$this->sample();$s['voiceprint']=$value;$this->assertSame([],(new Policy)->enroll([$s])['samples']);}}
 public function test_unreviewed_and_incompatible_samples_are_excluded():void {foreach(['validation_state'=>'unreviewed','voiceprint_model'=>'other','voiceprint_revision'=>'old']as$k=>$v){$s=$this->sample();$s[$k]=$v;$this->assertSame([],(new Policy)->enroll([$s])['samples']);}}
 public function test_duplicate_across_identities_is_flagged_without_deleting():void {$a=$this->sample();$b=$this->sample(2,'two');$b['voiceprint']=$a['voiceprint'];$r=(new Policy)->enroll([$a,$b]);$this->assertCount(0,$r['samples']);$this->assertSame('cross_identity_duplicate',$r['issues'][1]);$this->assertSame('cross_identity_duplicate',$r['issues'][2]);}
 public function test_quality_flags_reject_samples():void {foreach(['silence','noise','music','overlap','clipping']as$f){$s=$this->sample();$s['quality_review'][$f]=true;$this->assertEmpty((new Policy)->enroll([$s])['samples']);}}
 public function test_supported_match_uses_provider_score_not_probability():void {$r=(new Policy)->normalize($this->providerOutput(),$this->enrollment())['identification'][0];$this->assertSame('accepted',$r['status']);$this->assertSame('Name one',$r['recognized_identity']);$this->assertSame('provider_confidence_0_100',$r['score_kind']);}
 public function test_ambiguous_unknown_unregistered_and_short_speech():void {foreach([['sample:1'=>80,'sample:2'=>78],['sample:1'=>30,'sample:2'=>20],['other'=>99]]as$scores)$this->assertSame('unknown',(new Policy)->normalize($this->providerOutput($scores),$this->enrollment())['identification'][0]['status']);$o=$this->providerOutput();$o['diarization'][0]['end']=1;$this->assertSame('short_speech',(new Policy)->normalize($o,$this->enrollment())['identification'][0]['reason']);}
 public function test_unconfigured_acceptance_remains_unknown():void {config(['speaker-identification.threshold'=>null]);$this->assertSame('unknown',(new Policy)->normalize($this->providerOutput(),$this->enrollment())['identification'][0]['status']);}
 public function test_overlap_remains_unknown():void {$o=$this->providerOutput();$o['diarization'][]=['speaker'=>'SPEAKER_01','start'=>2,'end'=>4];$r=(new Policy)->normalize($o,$this->enrollment());$this->assertSame('overlapping_speech',$r['identification'][0]['reason']);}
 public function test_silence_returns_no_identity():void {$o=['diarization'=>[],'voiceprints'=>[]];$this->assertSame([],(new Policy)->normalize($o,$this->enrollment())['identification']);}
 public function test_malformed_output_is_failure():void {$this->expectException(\RuntimeException::class);(new Policy)->normalize([],[]);}
 public function test_no_nearest_time_or_majority_propagation():void {$turns=(new Policy)->normalize($this->providerOutput(),$this->enrollment())['identification'];$segments=[['speaker'=>'A','start'=>0,'end'=>4000,'text'=>'one'],['speaker'=>'A','start'=>6000,'end'=>7000,'text'=>'other']];$r=(new SpeakerTaggingService)->tagSpeakers($segments,$turns);$this->assertSame('Name one',$r['taggedTranscript'][0]['actualSpeaker']);$this->assertArrayNotHasKey('actualSpeaker',$r['taggedTranscript'][1]);$this->assertSame([],$r['speakerMapping']);}
 public function test_distinct_unknown_labels_survive_and_stale_name_is_not_indexed():void {$s=[['speaker'=>'A','actualSpeaker'=>'Wrong','start'=>0,'end'=>1000,'text'=>'one'],['speaker'=>'B','actualSpeaker'=>'Wrong','start'=>1000,'end'=>2000,'text'=>'two']];$r=(new SpeakerTaggingService)->tagSpeakers($s,[])['taggedTranscript'];$mapped=(new TranscriptSegmentMapper)->map($r,'milliseconds');$this->assertSame(['A','B'],array_column($mapped,'transcript_speaker'));$this->assertSame(['Unknown Speaker','Unknown Speaker'],array_column($mapped,'speaker'));}
 public function test_manual_correction_and_retry_are_preserved():void {$s=[['speaker'=>'A','actualSpeaker'=>'Human correction','identity_source'=>'manual','start'=>0,'end'=>1000,'text'=>'one']];$service=new SpeakerTaggingService;$a=$service->tagSpeakers($s,[])['taggedTranscript'];$b=$service->tagSpeakers($a,[])['taggedTranscript'];$this->assertSame($a,$b);$this->assertSame('Human correction',(new TranscriptSegmentMapper)->map($b,'milliseconds')[0]['speaker']);}
 public function test_raw_legacy_identification_cannot_tag_a_name():void {$r=(new SpeakerTaggingService)->tagSpeakers([['speaker'=>'A','text'=>'one','start'=>0,'end'=>1000]],[['speaker'=>'Famous','start'=>0,'end'=>1,'match'=>'Famous']]);$this->assertArrayNotHasKey('actualSpeaker',$r['taggedTranscript'][0]);}
}
